function daysAgoISO(n) {
  const d = new Date();
  d.setDate(d.getDate() - n);
  return d.toISOString();
}

function clamp(v, min, max) {
  return Math.max(min, Math.min(max, v));
}

const seedDailyVitals = (() => {
  const days = 30;
  const out = [];
  let hrv = 60, recovery = 65, sleep = 6.5, strain = 11;
  for (let i = days; i >= 0; i--) {
    hrv = clamp(hrv + (Math.random() - 0.5) * 8, 42, 92);
    recovery = clamp(recovery + (Math.random() - 0.5) * 12, 28, 98);
    sleep = clamp(sleep + (Math.random() - 0.5) * 1.1, 4.8, 8.8);
    strain = clamp(strain + (Math.random() - 0.5) * 4, 4, 20);
    out.push({
      id: uid(), loggedAt: daysAgoISO(i),
      hrv: Math.round(hrv), recovery: Math.round(recovery),
      sleep: Math.round(sleep * 10) / 10, strain: Math.round(strain * 10) / 10,
    });
  }
  // keep today's entry in sync with the vitals strip up top
  out[out.length - 1] = { ...out[out.length - 1], hrv: 68, recovery: 82, sleep: 7.2, strain: 14.3 };
  return out;
})();

