function localFoodSearch(query, customFoods) {
  const q = query.trim().toLowerCase();
  if (q.length < 2) return [];
  const pool = (customFoods && customFoods.length) ? [...customFoods, ...FOOD_DB] : FOOD_DB;
  return pool.filter((f) => f.name.toLowerCase().includes(q)).slice(0, 6);
}

