// Same derivations OverallTab uses for its diagnostic panels, factored out so
// Home can show the identical numbers in the same style without duplicating
// the logic inline (and risking the two screens drifting out of sync).
// Active burn = actual logged workout calories today (real, from your log).
// TDEE estimate = Basal Metabolic Rate (Mifflin-St Jeor, needs weight/height/
// age/sex) x 1.2 for baseline daily movement, PLUS that same active burn on
// top -- so it reflects what you actually did today rather than a generic
// activity-level guess. This is a standard formula, not a measured value --
// always shown labeled as an estimate.
function computeTDEE({ labs, workouts, profile }) {
  const now = new Date();
  const activeBurn = workouts.filter((w) => w.loggedAt && new Date(w.loggedAt).toDateString() === now.toDateString()).reduce((s, w) => s + (w.calories || 0), 0);

  const bodyComp = labs.filter((l) => l.category === "Body Composition");
  const weightEntries = bodyComp.filter((l) => l.marker.toLowerCase().includes("weight"));
  const weightKg = weightEntries.length ? weightEntries[0].value : null;

  if (!weightKg) return { ready: false, missing: "weight", activeBurn, bmr: null, tdeeToday: null };

  const { heightCm, age, sex } = profile || {};
  if (!heightCm || !age) return { ready: false, missing: "profile", activeBurn, bmr: null, tdeeToday: null };

  const h = Number(heightCm), a = Number(age), w = Number(weightKg);
  const bmr = sex === "Female" ? (10 * w + 6.25 * h - 5 * a - 161) : (10 * w + 6.25 * h - 5 * a + 5);
  const tdeeToday = Math.round(bmr * 1.2 + activeBurn);
  return { ready: true, missing: null, activeBurn, bmr: Math.round(bmr), tdeeToday };
}

function TDEESetupInline({ profile, onSave, missing }) {
  const [heightCm, setHeightCm] = useState(profile.heightCm);
  const [age, setAge] = useState(profile.age);
  const [sex, setSex] = useState(profile.sex || "Male");

  if (missing === "weight") {
    return (
      <p style={{ fontFamily: FONT_BODY, fontSize: 10.5, color: "#5C90B8", marginTop: 8, marginBottom: 0 }}>
        Log a weight in Labs → Body Composition to unlock a TDEE estimate here.
      </p>
    );
  }
  return (
    <div style={{ marginTop: 8, paddingTop: 8, borderTop: "1px solid rgba(47,217,192,0.22)" }}>
      <p style={{ fontFamily: FONT_BODY, fontSize: 10, color: "#5C90B8", marginTop: 0, marginBottom: 6 }}>
        Add height, age, and sex once to also see a TDEE estimate here (used only for this calculation).
      </p>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 6 }}>
        <input style={miniInputStyle} type="number" placeholder="Height cm" value={heightCm} onChange={(e) => setHeightCm(e.target.value)} />
        <input style={miniInputStyle} type="number" placeholder="Age" value={age} onChange={(e) => setAge(e.target.value)} />
        <select style={miniInputStyle} value={sex} onChange={(e) => setSex(e.target.value)}>
          <option>Male</option><option>Female</option>
        </select>
      </div>
      <PrimaryButton onClick={() => onSave({ heightCm, age, sex })} color={C.teal}>Save</PrimaryButton>
    </div>
  );
}

function computeHomeDiagnostics({ labs, workouts, meds, injuries, vitals }) {
  const now = new Date();
  const bodyComp = labs.filter((l) => l.category === "Body Composition");
  const bloodwork = labs.filter((l) => (l.category || "Bloodwork") === "Bloodwork");
  const homeTesting = labs.filter((l) => l.category === "Home Testing");
  const flagged = [...bloodwork, ...homeTesting].filter((l) => l.flag === "high" || l.flag === "low");
  const heartFlags = flagged.filter((l) => ORGAN_LAB_KEYWORDS.heart.some((kw) => l.marker.toLowerCase().includes(kw)));

  const latestByMarker = (sub) => { const m = bodyComp.filter((l) => l.marker.toLowerCase().includes(sub)); return m.length ? m[0] : null; };
  const latestBMI = latestByMarker("bmi");
  const latestBodyFat = latestByMarker("body fat") || latestByMarker("fat mass");
  const latestSMM = latestByMarker("skeletal muscle");
  const latestWater = latestByMarker("body water");
  const glucoseReadings = homeTesting.filter((l) => l.marker === "Blood Glucose");
  const latestGlucose = glucoseReadings.length ? glucoseReadings[0] : null;

  const monthWorkouts = workouts.filter((w) => w.loggedAt && new Date(w.loggedAt).getMonth() === now.getMonth() && new Date(w.loggedAt).getFullYear() === now.getFullYear());
  const monthMinutes = monthWorkouts.reduce((s, w) => s + (w.duration || 0), 0);
  const todayBurned = workouts.filter((w) => w.loggedAt && new Date(w.loggedAt).toDateString() === now.toDateString()).reduce((s, w) => s + (w.calories || 0), 0);
  const trainingConsistency = Math.round(Math.min(100, (monthWorkouts.length / 12) * 100));
  const sleepScoreVal = Math.round(Math.min(100, (vitals.sleep.value / 8) * 100));

  const activeInjuries = injuries.filter((i) => i.status === "active");
  const linkedCount = (id) => workouts.filter((w) => w.injuryId === id).length + meds.filter((m) => m.injuryId === id).length;
  const injuryRiskScore = activeInjuries.length === 0 ? 8 : Math.max(5, Math.min(95, 10 + activeInjuries.reduce((sum, i) => {
    const base = i.severity === "Severe" ? 35 : i.severity === "Moderate" ? 20 : 10;
    const daysSince = Math.max(0, (now - new Date(i.notedAt)) / 86400000);
    const recencyMultiplier = Math.max(0.25, 1 - daysSince / 45);
    const managementMultiplier = Math.max(0.5, 1 - linkedCount(i.id) * 0.05);
    return sum + base * recencyMultiplier * managementMultiplier;
  }, 0)));
  const injuryRiskLabel = injuryRiskScore < 25 ? "LOW" : injuryRiskScore < 60 ? "MODERATE" : "HIGH";
  const injuryRiskColor = injuryRiskScore < 25 ? C.teal : injuryRiskScore < 60 ? C.amber : C.coral;

  // A simple, transparent "readiness" score in the spirit of Whoop's daily
  // score -- but not their proprietary algorithm. It's a plain weighted
  // blend of what this app actually has: recovery %, a sleep score derived
  // from hours logged, and recent strain (inverted, since lower recent
  // strain generally means more readiness to push hard today).
  const strainReadiness = Math.max(0, 100 - (vitals.strain.value / 21) * 100);
  const readinessScore = Math.round(vitals.recovery.value * 0.45 + sleepScoreVal * 0.35 + strainReadiness * 0.20);
  const readinessLabel = readinessScore >= 70 ? "READY" : readinessScore >= 45 ? "MODERATE" : "LOW";
  const readinessColor = readinessScore >= 70 ? C.teal : readinessScore >= 45 ? C.amber : C.coral;

  return {
    latestBMI, latestBodyFat, latestSMM, latestWater, latestGlucose, heartFlags,
    monthWorkouts, monthMinutes, todayBurned, trainingConsistency, sleepScoreVal,
    activeInjuries, injuryRiskScore, injuryRiskLabel, injuryRiskColor,
    readinessScore, readinessLabel, readinessColor,
  };
}

// ---- small shared components ----
function Sparkline({ data, color }) {
  const w = 100, h = 28;
  const min = Math.min(...data), max = Math.max(...data);
  const range = max - min || 1;
  const pts = data.map((v, i) => `${(i / (data.length - 1)) * w},${h - ((v - min) / range) * h}`).join(" ");
  return (
    <svg width={w} height={h} viewBox={`0 0 ${w} ${h}`} style={{ display: "block" }}>
      <polyline points={pts} fill="none" stroke={color} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

function TrendIcon({ status }) {
  if (status === "good") return <TrendingUp size={12} color={C.teal} />;
  if (status === "bad") return <TrendingDown size={12} color={C.coral} />;
  return <Minus size={12} color={C.textMuted} />;
}

function VitalsStrip({ vitals }) {
  return (
    <div style={{ display: "flex", gap: 10, overflowX: "auto", padding: "2px 0 6px", WebkitOverflowScrolling: "touch" }}>
      {Object.values(vitals).map((v) => (
        <div key={v.label} style={{
          minWidth: 122, background: C.surface, border: `1px solid ${C.outline}`,
          borderRadius: 10, padding: "10px 12px", flexShrink: 0,
        }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span style={{ fontFamily: FONT_BODY, fontSize: 11, color: C.textSecondary, letterSpacing: 0.3, textTransform: "uppercase" }}>{v.label}</span>
            <TrendIcon status={v.status} />
          </div>
          <div style={{ fontFamily: FONT_DISPLAY, fontSize: 22, color: C.textPrimary, marginTop: 2 }}>
            {v.value}<span style={{ fontSize: 12, color: C.textMuted, marginLeft: 2 }}>{v.unit}</span>
          </div>
          <div style={{ marginTop: 4 }}>
            <Sparkline data={v.trend} color={v.status === "good" ? C.teal : v.status === "bad" ? C.coral : C.textMuted} />
          </div>
        </div>
      ))}
    </div>
  );
}

function SectionHeader({ title, action }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", margin: "18px 0 10px" }}>
      <span style={{ fontFamily: FONT_BODY, fontSize: 13, color: C.textSecondary, letterSpacing: 0.4, textTransform: "uppercase" }}>{title}</span>
      {action}
    </div>
  );
}

function AddButton({ onClick, label, icon: Icon = Plus }) {
  return (
    <button onClick={onClick} style={{
      display: "flex", alignItems: "center", gap: 4, background: "transparent",
      border: `1px solid ${C.borderStrong}`, color: C.teal, borderRadius: 8,
      padding: "5px 10px", fontFamily: FONT_BODY, fontSize: 12, cursor: "pointer",
    }}>
      <Icon size={13} /> {label}
    </button>
  );
}

function IconButton({ onClick, color = C.textMuted, children }) {
  return (
    <button onClick={onClick} style={{
      background: "transparent", border: "none", color, cursor: "pointer",
      display: "flex", alignItems: "center", padding: 4,
    }}>
      {children}
    </button>
  );
}

function Card({ children }) {
  return (
    <div style={{ background: C.surface, border: `1px solid ${C.outline}`, borderRadius: 10, padding: "12px 14px", marginBottom: 8 }}>
      {children}
    </div>
  );
}

function Field({ label, children }) {
  return (
    <label style={{ display: "block", marginBottom: 10 }}>
      <span style={{ display: "block", fontFamily: FONT_BODY, fontSize: 11, color: C.textSecondary, marginBottom: 4, textTransform: "uppercase", letterSpacing: 0.3 }}>{label}</span>
      {children}
    </label>
  );
}

const inputStyle = {
  width: "100%", boxSizing: "border-box", background: C.surfaceRaised, border: `1px solid ${C.border}`,
  borderRadius: 8, padding: "8px 10px", color: C.textPrimary, fontFamily: FONT_BODY, fontSize: 13, outline: "none",
};

const miniInputStyle = { ...inputStyle, padding: "6px 8px", fontSize: 12 };

function Modal({ title, onClose, children }) {
  return (
    <div style={{
      position: "absolute", inset: 0, background: "rgba(6,12,13,0.72)",
      display: "flex", alignItems: "flex-end", zIndex: 20, borderRadius: 28,
    }} onClick={onClose}>
      <div onClick={(e) => e.stopPropagation()} style={{
        width: "100%", background: C.surface, borderTop: `1px solid ${C.borderStrong}`,
        borderRadius: "18px 18px 0 0", padding: "16px 18px 22px", maxHeight: "80%", overflowY: "auto",
      }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
          <span style={{ fontFamily: FONT_BODY, fontSize: 14, color: C.textPrimary, fontWeight: 600 }}>{title}</span>
          <X size={18} color={C.textSecondary} onClick={onClose} style={{ cursor: "pointer" }} />
        </div>
        {children}
      </div>
    </div>
  );
}

function PrimaryButton({ children, onClick, color = C.teal }) {
  return (
    <button onClick={onClick} style={{
      width: "100%", background: color, color: C.bg, border: "none", borderRadius: 8,
      padding: "10px 0", fontFamily: FONT_BODY, fontSize: 13, fontWeight: 600, cursor: "pointer", marginTop: 4,
    }}>
      {children}
    </button>
  );
}

function ConfirmDelete({ label, onCancel, onConfirm }) {
  return (
    <Modal title={`Delete ${label}?`} onClose={onCancel}>
      <p style={{ fontFamily: FONT_BODY, fontSize: 13, color: C.textSecondary, marginTop: 0 }}>
        This removes the entry for good. This can't be undone.
      </p>
      <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
        <button onClick={onCancel} style={{
          flex: 1, background: "transparent", border: `1px solid ${C.borderStrong}`, color: C.textSecondary,
          borderRadius: 8, padding: "10px 0", fontFamily: FONT_BODY, fontSize: 13, cursor: "pointer",
        }}>Cancel</button>
        <button onClick={onConfirm} style={{
          flex: 1, background: C.coral, border: "none", color: C.bg,
          borderRadius: 8, padding: "10px 0", fontFamily: FONT_BODY, fontSize: 13, fontWeight: 600, cursor: "pointer",
        }}>Delete</button>
      </div>
    </Modal>
  );
}

// ---- home customization ----
function CustomizeHomeModal({ config, onClose, onToggle, onMove, onSetStyle }) {
  return (
    <Modal title="Customize home" onClose={onClose}>
      <p style={{ fontFamily: FONT_BODY, fontSize: 12, color: C.textMuted, marginTop: 0 }}>
        Choose what shows on your home screen, in what order, and — for score widgets — ring or bar style.
      </p>
      {config.map((item, i) => (
        <div key={item.key} style={{
          display: "flex", alignItems: "center", justifyContent: "space-between",
          padding: "10px 0", borderBottom: i < config.length - 1 ? `1px solid ${C.border}` : "none", gap: 8,
        }}>
          <label style={{ display: "flex", alignItems: "center", gap: 10, cursor: "pointer", minWidth: 0 }}>
            <input type="checkbox" checked={item.enabled} onChange={() => onToggle(item.key)} style={{ accentColor: C.teal, width: 15, height: 15, flexShrink: 0 }} />
            <span style={{ fontFamily: FONT_BODY, fontSize: 13, color: item.enabled ? C.textPrimary : C.textMuted, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{WIDGET_LIBRARY[item.key]}</span>
          </label>
          <div style={{ display: "flex", alignItems: "center", gap: 6, flexShrink: 0 }}>
            {SCORE_WIDGET_KEYS.includes(item.key) && (
              <div style={{ display: "flex", background: C.surfaceRaised, borderRadius: 7, padding: 2 }}>
                {["ring", "bar"].map((s) => (
                  <button key={s} onClick={() => onSetStyle(item.key, s)} style={{
                    border: "none", borderRadius: 5, padding: "3px 8px", cursor: "pointer",
                    background: item.style === s ? C.teal : "transparent",
                    fontFamily: FONT_BODY, fontSize: 10, color: item.style === s ? C.bg : C.textMuted,
                  }}>{s === "ring" ? "Ring" : "Bar"}</button>
                ))}
              </div>
            )}
            <IconButton onClick={() => onMove(i, -1)}><ChevronUp size={16} /></IconButton>
            <IconButton onClick={() => onMove(i, 1)}><ChevronDown size={16} /></IconButton>
          </div>
        </div>
      ))}
    </Modal>
  );
}

// ---- dashboard widgets ----
function TodayStatsWidget({ meals, meds, workouts, labs, userProfile, setUserProfile }) {
  const totalCals = meals.reduce((s, m) => s + m.cals, 0);
  const pendingMeds = meds.filter((m) => !m.takenToday).length;
  const tdee = computeTDEE({ labs, workouts, profile: userProfile });
  return (
    <div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
        <Card>
          <div style={{ display: "flex", alignItems: "center", gap: 5, color: C.textSecondary, fontFamily: FONT_BODY, fontSize: 10 }}>
            <UtensilsCrossed size={12} /> INTAKE
          </div>
          <div style={{ fontFamily: FONT_DISPLAY, fontSize: 17, color: C.textPrimary, marginTop: 4 }}>{totalCals}<span style={{ fontSize: 10, color: C.textMuted, marginLeft: 2 }}>kcal</span></div>
        </Card>
        <Card>
          <div style={{ display: "flex", alignItems: "center", gap: 5, color: C.textSecondary, fontFamily: FONT_BODY, fontSize: 10 }}>
            <Flame size={12} /> ACTIVE BURN
          </div>
          <div style={{ fontFamily: FONT_DISPLAY, fontSize: 17, color: C.coral, marginTop: 4 }}>{tdee.activeBurn}<span style={{ fontSize: 10, color: C.textMuted, marginLeft: 2 }}>kcal</span></div>
        </Card>
        <Card>
          <div style={{ display: "flex", alignItems: "center", gap: 5, color: C.textSecondary, fontFamily: FONT_BODY, fontSize: 10 }}>
            <Flame size={12} /> TDEE EST.
          </div>
          <div style={{ fontFamily: FONT_DISPLAY, fontSize: 17, color: C.textPrimary, marginTop: 4 }}>{tdee.ready ? tdee.tdeeToday : "—"}<span style={{ fontSize: 10, color: C.textMuted, marginLeft: 2 }}>kcal</span></div>
        </Card>
        <Card>
          <div style={{ display: "flex", alignItems: "center", gap: 5, color: C.textSecondary, fontFamily: FONT_BODY, fontSize: 10 }}>
            <Pill size={12} /> PROTOCOL
          </div>
          <div style={{ fontFamily: FONT_DISPLAY, fontSize: 17, color: pendingMeds ? C.amber : C.teal, marginTop: 4 }}>{pendingMeds}<span style={{ fontSize: 10, color: C.textMuted, marginLeft: 2 }}>due</span></div>
        </Card>
      </div>
      {!tdee.ready && <TDEESetupInline profile={userProfile} missing={tdee.missing} onSave={setUserProfile} />}
    </div>
  );
}

function MacrosWidget({ meals }) {
  const totals = meals.reduce((s, m) => ({ cals: s.cals + m.cals, protein: s.protein + m.protein, carbs: s.carbs + m.carbs, fat: s.fat + m.fat }), { cals: 0, protein: 0, carbs: 0, fat: 0 });
  return (
    <Card>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 6, textAlign: "center" }}>
        {[["kcal", totals.cals], ["protein", totals.protein + "g"], ["carbs", totals.carbs + "g"], ["fat", totals.fat + "g"]].map(([l, v]) => (
          <div key={l}>
            <div style={{ fontFamily: FONT_DISPLAY, fontSize: 15, color: C.textPrimary }}>{v}</div>
            <div style={{ fontFamily: FONT_BODY, fontSize: 10, color: C.textMuted, textTransform: "uppercase" }}>{l}</div>
          </div>
        ))}
      </div>
    </Card>
  );
}

function LatestSessionWidget({ workouts }) {
  if (!workouts.length) return null;
  const w = workouts[0];
  return (
    <Card>
      <div style={{ display: "flex", justifyContent: "space-between" }}>
        <span style={{ fontFamily: FONT_BODY, fontSize: 13, color: C.textPrimary }}>{w.name}</span>
        <span style={{ fontFamily: FONT_BODY, fontSize: 11, color: C.textMuted }}>{w.date}</span>
      </div>
      <div style={{ fontFamily: FONT_BODY, fontSize: 11, color: C.textSecondary, marginTop: 2 }}>{w.type} · {w.duration} min</div>
    </Card>
  );
}

function MedsDueWidget({ meds }) {
  const due = meds.filter((m) => !m.takenToday);
  if (!due.length) return <Card><span style={{ fontFamily: FONT_BODY, fontSize: 12, color: C.textMuted }}>Nothing due — protocol complete.</span></Card>;
  return (
    <Card>
      {due.map((m) => (
        <div key={m.id} style={{ display: "flex", justifyContent: "space-between", padding: "3px 0", fontFamily: FONT_BODY, fontSize: 12, color: C.textSecondary }}>
          <span>{m.name}</span><span style={{ color: C.textMuted }}>{m.dose}</span>
        </div>
      ))}
    </Card>
  );
}

function LabsFlagsWidget({ labs }) {
  const flagged = labs.filter((l) => l.flag !== "normal");
  if (!flagged.length) return <Card><span style={{ fontFamily: FONT_BODY, fontSize: 12, color: C.textMuted }}>All markers in range.</span></Card>;
  return (
    <Card>
      {flagged.map((l) => (
        <div key={l.id} style={{ display: "flex", justifyContent: "space-between", padding: "3px 0", fontFamily: FONT_BODY, fontSize: 12 }}>
          <span style={{ color: C.textSecondary }}>{l.marker}</span>
          <span style={{ color: C.coral, fontFamily: FONT_DISPLAY }}>{l.value} {l.unit}</span>
        </div>
      ))}
    </Card>
  );
}

function DashboardTab({ vitals, workouts, meals, meds, labs, injuries, waterCups, addWaterCup, userProfile, setUserProfile, homeConfig, onOpenCustomize, onOpenCalendar }) {
  const diag = computeHomeDiagnostics({ labs, workouts, meds, injuries, vitals });

  const scoreWidgetConfig = {
    readinessPanel: { title: "Readiness", value: diag.readinessScore, color: diag.readinessColor, sublabel: diag.readinessLabel },
    recoveryPanel: { title: "Recovery", value: vitals.recovery.value, color: C.teal, sublabel: "score" },
    sleepPanel: { title: "Sleep", value: diag.sleepScoreVal, color: C.teal, sublabel: `${vitals.sleep.value}h` },
    trainingPanel: { title: "Training", value: diag.trainingConsistency, color: C.teal, sublabel: `${diag.monthWorkouts.length} sess.` },
    injuryRiskPanel: { title: "Injury Risk", value: diag.injuryRiskScore, color: diag.injuryRiskColor, sublabel: diag.injuryRiskLabel },
    hydrationPanel: {
      title: "Hydration", value: Math.min(100, (waterCups / 8) * 100), color: C.teal, sublabel: `${waterCups}/8`,
      action: (
        <button onClick={addWaterCup} style={{ background: "rgba(47,217,192,0.15)", border: "none", borderRadius: 6, padding: "3px 8px", cursor: "pointer" }}>
          <span style={{ fontFamily: FONT_BODY, fontSize: 10, color: C.teal }}>+1 cup</span>
        </button>
      ),
    },
  };

  const renderScoreCard = (w) => {
    const cfg = scoreWidgetConfig[w.key];
    if (!cfg) return null;
    return (
      <DarkPanel key={w.key} title={cfg.title} action={cfg.action}>
        {w.style === "bar" ? (
          <HealthBar value={cfg.value} color={cfg.color} label={cfg.title} sublabel={cfg.sublabel} />
        ) : (
          <div style={{ display: "flex", justifyContent: "center" }}>
            <RadialGauge value={cfg.value} color={cfg.color} size={64} sublabel={cfg.sublabel} />
          </div>
        )}
      </DarkPanel>
    );
  };

  // Group consecutive enabled score-widgets (ring/bar toggleable) into a
  // 2-column dashboard grid, Apple/Whoop-style; everything else stays
  // full-width in its existing spot in the order the user set.
  const enabled = homeConfig.filter((w) => w.enabled);
  const blocks = [];
  let buffer = [];
  enabled.forEach((w) => {
    if (SCORE_WIDGET_KEYS.includes(w.key)) {
      buffer.push(w);
    } else {
      if (buffer.length) { blocks.push({ type: "grid", items: buffer }); buffer = []; }
      blocks.push({ type: "single", item: w });
    }
  });
  if (buffer.length) blocks.push({ type: "grid", items: buffer });

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", margin: "18px 0 10px", position: "relative" }}>
        <span style={{ fontFamily: FONT_BODY, fontSize: 13, color: C.textSecondary, letterSpacing: 0.4, textTransform: "uppercase" }}>Home</span>
        <button onClick={onOpenCalendar} style={{
          position: "absolute", left: "50%", transform: "translateX(-50%)",
          display: "flex", alignItems: "center", gap: 4, background: "transparent", border: "none", cursor: "pointer", padding: "2px 6px",
        }}>
          <CalendarDays size={12} color={C.textSecondary} />
          <span style={{ fontFamily: FONT_BODY, fontSize: 11, color: C.textSecondary, textDecoration: "underline", textDecorationColor: C.textSecondary }}>
            {new Date().toLocaleDateString([], { weekday: "short", month: "short", day: "numeric" })}
          </span>
        </button>
        <IconButton onClick={onOpenCustomize} color={C.textSecondary}><Settings2 size={17} /></IconButton>
      </div>

      {blocks.map((block, bi) => block.type === "grid" ? (
        <div key={`grid-${bi}`} style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginBottom: 4 }}>
          {block.items.map((w) => renderScoreCard(w))}
        </div>
      ) : (
        <div key={block.item.key} style={{ marginBottom: 4 }}>
          {block.item.key === "vitals" && <VitalsStrip vitals={vitals} />}
          {block.item.key === "todayStats" && <TodayStatsWidget meals={meals} meds={meds} workouts={workouts} labs={labs} userProfile={userProfile} setUserProfile={setUserProfile} />}
          {block.item.key === "macros" && <MacrosWidget meals={meals} />}
          {block.item.key === "latestSession" && (
            <>
              <SectionHeader title="Latest session" />
              <LatestSessionWidget workouts={workouts} />
            </>
          )}
          {block.item.key === "medsDue" && (
            <>
              <SectionHeader title="Meds due" />
              <MedsDueWidget meds={meds} />
            </>
          )}
          {block.item.key === "labsFlags" && (
            <>
              <SectionHeader title="Flagged labs" />
              <LabsFlagsWidget labs={labs} />
            </>
          )}
          {block.item.key === "bioVitalsPanel" && (
            <DarkPanel title="Bio Vitals" subtitle="Latest">
              {[["HRV", vitals.hrv], ["Recovery", vitals.recovery], ["Sleep", vitals.sleep], ["Strain", vitals.strain]].map(([l, v]) => (
                <div key={l} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
                  <div>
                    <div style={{ fontFamily: FONT_BODY, fontSize: 9, color: "#5C90B8" }}>{l}</div>
                    <div style={{ fontFamily: FONT_DISPLAY, fontSize: 15, color: "#EAF3FC" }}>{v.value}<span style={{ fontSize: 9, color: "#5C90B8", marginLeft: 2 }}>{v.unit}</span></div>
                  </div>
                  <DarkSparkline data={v.trend} color={C.teal} />
                </div>
              ))}
            </DarkPanel>
          )}
          {block.item.key === "bodyCompPanel" && (
            <DarkPanel title="Body Composition" subtitle={diag.latestBMI ? "Latest scan" : "No scan yet"}>
              {(diag.latestBodyFat || diag.latestSMM || diag.latestWater) ? (
                <>
                  {diag.latestSMM && <div style={{ display: "flex", justifyContent: "space-between", fontFamily: FONT_BODY, fontSize: 10.5, color: "#BFE0FA", marginBottom: 5 }}><span>● Muscle Mass</span><span style={{ fontFamily: FONT_DISPLAY }}>{diag.latestSMM.value}{diag.latestSMM.unit}</span></div>}
                  {diag.latestBodyFat && <div style={{ display: "flex", justifyContent: "space-between", fontFamily: FONT_BODY, fontSize: 10.5, color: "#BFE0FA", marginBottom: 5 }}><span>● Body Fat</span><span style={{ fontFamily: FONT_DISPLAY }}>{diag.latestBodyFat.value}{diag.latestBodyFat.unit}</span></div>}
                  {diag.latestWater && <div style={{ display: "flex", justifyContent: "space-between", fontFamily: FONT_BODY, fontSize: 10.5, color: "#BFE0FA" }}><span>● Water</span><span style={{ fontFamily: FONT_DISPLAY }}>{diag.latestWater.value}{diag.latestWater.unit}</span></div>}
                </>
              ) : <span style={{ fontFamily: FONT_BODY, fontSize: 11, color: "#5C90B8" }}>Log a scan in the Labs tab to see this.</span>}
            </DarkPanel>
          )}
          {block.item.key === "heartHealthPanel" && (
            <DarkPanel title="Heart Health" subtitle="From logged bloodwork">
              <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <RadialGauge value={diag.heartFlags.length > 0 ? 40 : 90} color={diag.heartFlags.length > 0 ? C.coral : C.teal} sublabel={diag.heartFlags.length > 0 ? "flagged" : "no flags"} />
                <div style={{ flex: 1 }}>
                  {diag.heartFlags.length > 0 ? diag.heartFlags.map((l) => (
                    <div key={l.id} style={{ fontFamily: FONT_BODY, fontSize: 10, color: C.coral, marginBottom: 2 }}>{l.marker}: {l.value} {l.unit}</div>
                  )) : <span style={{ fontFamily: FONT_BODY, fontSize: 10.5, color: "#5C90B8" }}>No cardiovascular markers flagged.</span>}
                </div>
              </div>
            </DarkPanel>
          )}
          {block.item.key === "metabolicPanel" && (() => {
            const tdee = computeTDEE({ labs, workouts, profile: userProfile });
            return (
              <DarkPanel title="Metabolic Panel" subtitle="Today">
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 6 }}>
                  <div>
                    <div style={{ fontFamily: FONT_BODY, fontSize: 9, color: "#5C90B8" }}>ACTIVE BURN</div>
                    <div style={{ fontFamily: FONT_DISPLAY, fontSize: 16, color: "#EAF3FC" }}>{tdee.activeBurn}<span style={{ fontSize: 9, color: "#5C90B8", marginLeft: 2 }}>kcal</span></div>
                  </div>
                  <div>
                    <div style={{ fontFamily: FONT_BODY, fontSize: 9, color: "#5C90B8" }}>TDEE ESTIMATE</div>
                    <div style={{ fontFamily: FONT_DISPLAY, fontSize: 16, color: "#EAF3FC" }}>{tdee.ready ? tdee.tdeeToday : "—"}<span style={{ fontSize: 9, color: "#5C90B8", marginLeft: 2 }}>kcal</span></div>
                  </div>
                </div>
                {diag.latestGlucose && (
                  <div>
                    <div style={{ fontFamily: FONT_BODY, fontSize: 9, color: "#5C90B8" }}>GLUCOSE</div>
                    <div style={{ fontFamily: FONT_DISPLAY, fontSize: 16, color: "#EAF3FC" }}>{diag.latestGlucose.value}<span style={{ fontSize: 9, color: "#5C90B8", marginLeft: 2 }}>{diag.latestGlucose.unit}</span></div>
                  </div>
                )}
                {!tdee.ready && <TDEESetupInline profile={userProfile} missing={tdee.missing} onSave={setUserProfile} />}
              </DarkPanel>
            );
          })()}
        </div>
      ))}
      {enabled.length === 0 && (
        <Card><span style={{ fontFamily: FONT_BODY, fontSize: 12, color: C.textMuted }}>Nothing on your home screen yet. Tap the gear to add widgets.</span></Card>
      )}
    </div>
  );
}

// ---- simulated heart rate ----
function HeartRateMonitor({ running, phase }) {
  const [bpm, setBpm] = useState(92);
  const [trend, setTrend] = useState([92]);
  const intervalRef = useRef(null);

  useEffect(() => {
    if (running) {
      intervalRef.current = setInterval(() => {
        setBpm((prev) => {
          const target = phase === "work" ? 158 : phase === "rest" ? 112 : 130;
          const drift = (target - prev) * 0.25 + (Math.random() * 8 - 4);
          const next = Math.round(Math.min(190, Math.max(70, prev + drift)));
          setTrend((t) => [...t.slice(-23), next]);
          return next;
        });
      }, 1000);
    }
    return () => clearInterval(intervalRef.current);
  }, [running, phase]);

  return (
    <div style={{
      background: C.surfaceRaised, border: `1px solid ${C.outline}`, borderRadius: 10,
      padding: "10px 14px", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10,
    }}>
      <div>
        <div style={{ display: "flex", alignItems: "center", gap: 5, fontFamily: FONT_BODY, fontSize: 10, color: C.textMuted, textTransform: "uppercase", letterSpacing: 0.3 }}>
          <Heart size={11} color={C.coral} style={running ? { animation: "hr-pulse 0.9s ease-in-out infinite" } : undefined} /> Heart rate
        </div>
        <div style={{ fontFamily: FONT_DISPLAY, fontSize: 22, color: C.textPrimary, marginTop: 2 }}>{bpm}<span style={{ fontSize: 11, color: C.textMuted, marginLeft: 3 }}>bpm</span></div>
      </div>
      <Sparkline data={trend.length > 1 ? trend : [trend[0], trend[0]]} color={C.coral} />
      <style>{`@keyframes hr-pulse { 0%,100% { transform: scale(1); } 50% { transform: scale(1.3); } }`}</style>
    </div>
  );
}

// ---- interval timer ----
function IntervalRunner({ workout, onExit }) {
  const { work, rest, rounds } = workout.intervals;
  const [phase, setPhase] = useState("work");
  const [round, setRound] = useState(1);
  const [remaining, setRemaining] = useState(work);
  const [running, setRunning] = useState(false);
  const [finished, setFinished] = useState(false);
  const intervalRef = useRef(null);

  useEffect(() => {
    if (running && !finished) {
      intervalRef.current = setInterval(() => {
        setRemaining((r) => {
          if (r > 1) return r - 1;
          // phase boundary
          if (phase === "work") {
            if (rest > 0) {
              setPhase("rest");
              return rest;
            }
            if (round >= rounds) { setFinished(true); setRunning(false); return 0; }
            setRound((rd) => rd + 1);
            return work;
          }
          // rest -> next round or finish
          if (round >= rounds) { setFinished(true); setRunning(false); return 0; }
          setRound((rd) => rd + 1);
          setPhase("work");
          return work;
        });
      }, 1000);
    }
    return () => clearInterval(intervalRef.current);
  }, [running, phase, round, rounds, rest, work, finished]);

  const start = () => setRunning(true);
  const pause = () => setRunning(false);
  const reset = () => { setRunning(false); setFinished(false); setPhase("work"); setRound(1); setRemaining(work); };

  const mm = String(Math.floor(remaining / 60)).padStart(2, "0");
  const ss = String(remaining % 60).padStart(2, "0");
  const phaseColor = phase === "work" ? C.teal : C.amber;

  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 14 }}>
        <IconButton onClick={onExit} color={C.textSecondary}><ArrowLeft size={18} /></IconButton>
        <span style={{ fontFamily: FONT_BODY, fontSize: 14, color: C.textPrimary, fontWeight: 600 }}>{workout.name}</span>
      </div>

      <div style={{
        background: C.surface, border: `1px solid ${finished ? C.teal : C.outline}`, borderRadius: 14,
        padding: "26px 16px", textAlign: "center", marginBottom: 12,
      }}>
        {finished ? (
          <>
            <div style={{ fontFamily: FONT_DISPLAY, fontSize: 20, color: C.teal }}>SESSION COMPLETE</div>
            <div style={{ fontFamily: FONT_BODY, fontSize: 12, color: C.textSecondary, marginTop: 4 }}>{rounds} rounds logged</div>
          </>
        ) : (
          <>
            <div style={{ fontFamily: FONT_BODY, fontSize: 12, color: phaseColor, textTransform: "uppercase", letterSpacing: 1 }}>
              {phase === "work" ? "Work" : "Rest"}
            </div>
            <div style={{ fontFamily: FONT_DISPLAY, fontSize: 52, color: C.textPrimary, margin: "4px 0" }}>{mm}:{ss}</div>
            <div style={{ fontFamily: FONT_BODY, fontSize: 12, color: C.textMuted }}>Round {round} / {rounds}</div>
          </>
        )}
      </div>

      {!finished && (
        <div style={{ display: "flex", gap: 8, marginBottom: 12 }}>
          {!running ? (
            <PrimaryButton onClick={start} color={C.teal}>Start</PrimaryButton>
          ) : (
            <PrimaryButton onClick={pause} color={C.amber}>Pause</PrimaryButton>
          )}
          <button onClick={reset} style={{
            width: 44, background: "transparent", border: `1px solid ${C.borderStrong}`, color: C.textSecondary,
            borderRadius: 8, cursor: "pointer", marginTop: 4,
          }}><RotateCcw size={16} style={{ margin: "0 auto" }} /></button>
        </div>
      )}

      <SectionHeader title="Heart rate" />
      <HeartRateMonitor running={running && !finished} phase={phase} />
      <p style={{ fontFamily: FONT_BODY, fontSize: 11, color: C.textMuted, marginTop: 8 }}>
        Simulated for now — pair a chest strap or watch to see live readings here during background rest too.
      </p>
    </div>
  );
}

// ---- workout builder ----
function emptyExercise() {
  return { id: uid(), name: "", sets: 3, reps: 10, load: 0, rest: 60 };
}

function WorkoutBuilder({ initial, prefill, onCancel, onSave }) {
  const [name, setName] = useState(initial?.name || prefill?.name || "");
  const [type, setType] = useState(initial?.type || prefill?.type || "Strength");
  const [duration, setDuration] = useState(initial?.duration || "");
  const [calories, setCalories] = useState(initial?.calories || "");
  const [intervals, setIntervals] = useState(initial?.intervals || { work: 60, rest: 30, rounds: 8 });
  const injuryId = initial?.injuryId || prefill?.injuryId || null;
  const injuryLabel = initial?.injuryLabel || prefill?.injuryLabel || null;
  const [blocks, setBlocks] = useState(
    initial?.blocks?.length ? initial.blocks : [{ id: uid(), name: "", exercises: [emptyExercise()] }]
  );

  const addBlock = () => setBlocks((b) => [...b, { id: uid(), name: "", exercises: [emptyExercise()] }]);
  const removeBlock = (blockId) => setBlocks((b) => b.filter((bl) => bl.id !== blockId));
  const updateBlockName = (blockId, val) => setBlocks((b) => b.map((bl) => (bl.id === blockId ? { ...bl, name: val } : bl)));

  const addExercise = (blockId) => setBlocks((b) => b.map((bl) => (bl.id === blockId ? { ...bl, exercises: [...bl.exercises, emptyExercise()] } : bl)));
  const removeExercise = (blockId, exId) => setBlocks((b) => b.map((bl) => (bl.id === blockId ? { ...bl, exercises: bl.exercises.filter((e) => e.id !== exId) } : bl)));
  const updateExercise = (blockId, exId, field, val) => setBlocks((b) => b.map((bl) => (
    bl.id === blockId ? { ...bl, exercises: bl.exercises.map((e) => (e.id === exId ? { ...e, [field]: val } : e)) } : bl
  )));

  const save = () => {
    if (!name.trim()) return;
    const cleanedBlocks = blocks
      .map((bl) => ({ ...bl, exercises: bl.exercises.filter((e) => e.name.trim()) }))
      .filter((bl) => bl.exercises.length > 0);
    onSave({
      id: initial?.id || uid(),
      name, type, duration: Number(duration) || 0,
      calories: Number(calories) || 0,
      date: initial?.date || "Today",
      blocks: cleanedBlocks,
      intervals: type === "Cardio" ? intervals : null,
      loggedAt: initial?.loggedAt || new Date().toISOString(),
      injuryId, injuryLabel,
    });
  };

  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 14 }}>
        <IconButton onClick={onCancel} color={C.textSecondary}><ArrowLeft size={18} /></IconButton>
        <span style={{ fontFamily: FONT_BODY, fontSize: 14, color: C.textPrimary, fontWeight: 600 }}>
          {initial ? "Edit session" : "Build a session"}
        </span>
      </div>

      {injuryLabel && (
        <div style={{ display: "flex", alignItems: "center", gap: 6, background: C.coralDim, borderRadius: 8, padding: "7px 10px", marginBottom: 10 }}>
          <AlertCircle size={13} color={C.coral} />
          <span style={{ fontFamily: FONT_BODY, fontSize: 11, color: C.coral }}>Linked to recovery from: {injuryLabel}</span>
        </div>
      )}

      <Card>
        <Field label="Session name"><input style={inputStyle} value={name} onChange={(e) => setName(e.target.value)} placeholder="Leg day, push day..." /></Field>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
          <Field label="Type">
            <select style={inputStyle} value={type} onChange={(e) => setType(e.target.value)}>
              <option>Strength</option><option>Cardio</option><option>Mobility</option><option>Physio</option><option>Sport</option>
            </select>
          </Field>
          <Field label="Duration (min)"><input style={inputStyle} type="number" value={duration} onChange={(e) => setDuration(e.target.value)} placeholder="45" /></Field>
        </div>
        <Field label="Est. calories burned"><input style={inputStyle} type="number" value={calories} onChange={(e) => setCalories(e.target.value)} placeholder="350" /></Field>
      </Card>

      {type === "Cardio" && (
        <>
          <SectionHeader title="Intervals" />
          <Card>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 8 }}>
              <Field label="Work (sec)"><input style={miniInputStyle} type="number" value={intervals.work} onChange={(e) => setIntervals((iv) => ({ ...iv, work: Number(e.target.value) || 0 }))} /></Field>
              <Field label="Rest (sec)"><input style={miniInputStyle} type="number" value={intervals.rest} onChange={(e) => setIntervals((iv) => ({ ...iv, rest: Number(e.target.value) || 0 }))} /></Field>
              <Field label="Rounds"><input style={miniInputStyle} type="number" value={intervals.rounds} onChange={(e) => setIntervals((iv) => ({ ...iv, rounds: Number(e.target.value) || 1 }))} /></Field>
            </div>
            <p style={{ fontFamily: FONT_BODY, fontSize: 11, color: C.textMuted, margin: "4px 0 0" }}>
              Save the session, then hit the play icon on its card to run the interval timer with live heart rate.
            </p>
          </Card>
        </>
      )}

      <SectionHeader title="Blocks" />
      {blocks.map((bl, i) => (
        <div key={bl.id} style={{ background: C.surface, border: `1px solid ${C.outline}`, borderRadius: 10, padding: 12, marginBottom: 10 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
            <span style={{
              fontFamily: FONT_DISPLAY, fontSize: 13, color: C.teal, background: C.tealDim,
              width: 24, height: 24, borderRadius: 6, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0,
            }}>{blockLabel(i)}</span>
            <input style={{ ...inputStyle, flex: 1 }} placeholder="Block label (Warm-up, Main lift...)" value={bl.name} onChange={(e) => updateBlockName(bl.id, e.target.value)} />
            <IconButton onClick={() => removeBlock(bl.id)} color={C.coral}><Trash2 size={16} /></IconButton>
          </div>

          {bl.exercises.map((ex) => (
            <div key={ex.id} style={{ marginBottom: 8, paddingBottom: 8, borderBottom: `1px solid ${C.border}` }}>
              <div style={{ display: "flex", gap: 6, marginBottom: 6 }}>
                <input style={{ ...miniInputStyle, flex: 1 }} placeholder="Exercise name" value={ex.name} onChange={(e) => updateExercise(bl.id, ex.id, "name", e.target.value)} />
                <IconButton onClick={() => removeExercise(bl.id, ex.id)} color={C.textMuted}><X size={15} /></IconButton>
              </div>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr 1fr", gap: 6 }}>
                <div>
                  <span style={{ fontFamily: FONT_BODY, fontSize: 9, color: C.textMuted }}>SETS</span>
                  <input style={miniInputStyle} type="number" value={ex.sets} onChange={(e) => updateExercise(bl.id, ex.id, "sets", Number(e.target.value))} />
                </div>
                <div>
                  <span style={{ fontFamily: FONT_BODY, fontSize: 9, color: C.textMuted }}>REPS</span>
                  <input style={miniInputStyle} type="number" value={ex.reps} onChange={(e) => updateExercise(bl.id, ex.id, "reps", Number(e.target.value))} />
                </div>
                <div>
                  <span style={{ fontFamily: FONT_BODY, fontSize: 9, color: C.textMuted }}>LOAD KG</span>
                  <input style={miniInputStyle} type="number" value={ex.load} onChange={(e) => updateExercise(bl.id, ex.id, "load", Number(e.target.value))} />
                </div>
                <div>
                  <span style={{ fontFamily: FONT_BODY, fontSize: 9, color: C.textMuted }}>REST S</span>
                  <input style={miniInputStyle} type="number" value={ex.rest} onChange={(e) => updateExercise(bl.id, ex.id, "rest", Number(e.target.value))} />
                </div>
              </div>
            </div>
          ))}
          <AddButton onClick={() => addExercise(bl.id)} label="Add exercise" />
        </div>
      ))}
      <AddButton onClick={addBlock} label={`Add block ${blockLabel(blocks.length)}`} />

      <PrimaryButton onClick={save}>Save session</PrimaryButton>
    </div>
  );
}

function TrainFuelTab({
  workouts, addWorkout, updateWorkout, removeWorkout, pendingLink, clearPendingLink,
  meals, addMeal, removeMeal, customFoods, addCustomFood,
  labs, userProfile, setUserProfile,
}) {
  const [subTab, setSubTab] = useState("train");

  // if an injury's "Physio" link jumps here, make sure we land on the training side
  useEffect(() => {
    if (pendingLink && pendingLink.type === "physio") setSubTab("train");
  }, [pendingLink]);

  const todayStr = new Date().toDateString();
  const todayConsumed = meals.filter((m) => m.loggedAt && new Date(m.loggedAt).toDateString() === todayStr).reduce((s, m) => s + (m.cals || 0), 0);
  const tdee = computeTDEE({ labs, workouts, profile: userProfile });
  const outValue = tdee.ready ? tdee.tdeeToday : tdee.activeBurn;
  const barMax = Math.max(todayConsumed, outValue, 2000);
  const net = todayConsumed - outValue;

  return (
    <div>
      <DarkPanel title="Today" subtitle={`Net ${net >= 0 ? "+" : ""}${net} kcal`}>
        <div style={{ marginBottom: 10 }}>
          <HealthBar value={todayConsumed} max={barMax} color={C.teal} label="Consumed" sublabel="kcal" />
        </div>
        <div style={{ marginBottom: tdee.ready ? 10 : 0 }}>
          <HealthBar value={tdee.activeBurn} max={barMax} color={C.amber} label="Active Burn" sublabel="kcal logged" />
        </div>
        {tdee.ready && <HealthBar value={tdee.tdeeToday} max={barMax} color={C.coral} label="TDEE Estimate" sublabel="kcal" />}
        {!tdee.ready && <TDEESetupInline profile={userProfile} missing={tdee.missing} onSave={setUserProfile} />}
      </DarkPanel>

      <div style={{ display: "flex", gap: 6, marginBottom: 4 }}>
        {[["train", "Training"], ["fuel", "Fuel"]].map(([key, label]) => (
          <button key={key} onClick={() => setSubTab(key)} style={{
            flex: 1, border: "none", borderRadius: 10, cursor: "pointer", padding: "8px 0",
            background: subTab === key ? C.teal : C.surfaceRaised,
            fontFamily: FONT_BODY, fontSize: 12.5, fontWeight: 600, color: subTab === key ? C.bg : C.textSecondary,
          }}>{label}</button>
        ))}
      </div>
      {subTab === "train" ? (
        <TrainTab workouts={workouts} addWorkout={addWorkout} updateWorkout={updateWorkout} removeWorkout={removeWorkout} pendingLink={pendingLink} clearPendingLink={clearPendingLink} />
      ) : (
        <FuelTab meals={meals} addMeal={addMeal} removeMeal={removeMeal} customFoods={customFoods} addCustomFood={addCustomFood} />
      )}
    </div>
  );
}

function TrainTab({ workouts, addWorkout, updateWorkout, removeWorkout, pendingLink, clearPendingLink }) {
  const [mode, setMode] = useState("list"); // list | builder | interval
  const [editing, setEditing] = useState(null);
  const [prefill, setPrefill] = useState(null);
  const [active, setActive] = useState(null);
  const [confirmId, setConfirmId] = useState(null);

  const today = new Date();
  const todayOffset = today.getDay();
  const [weekStart, setWeekStart] = useState(() => { const d = new Date(today); d.setDate(d.getDate() - todayOffset); return d; });
  const [selectedDay, setSelectedDay] = useState(today);

  useEffect(() => {
    if (pendingLink && pendingLink.type === "physio") {
      setEditing(null);
      setPrefill({ type: "Physio", injuryId: pendingLink.injuryId, injuryLabel: pendingLink.injuryLabel });
      setMode("builder");
      clearPendingLink();
    }
  }, [pendingLink]);

  const openNew = () => { setEditing(null); setPrefill(null); setMode("builder"); };
  const openEdit = (w) => { setEditing(w); setPrefill(null); setMode("builder"); };
  const openInterval = (w) => { setActive(w); setMode("interval"); };
  const handleSave = (w) => {
    if (editing) updateWorkout(w); else addWorkout(w);
    setMode("list"); setEditing(null); setPrefill(null);
  };

  if (mode === "builder") {
    return <WorkoutBuilder initial={editing} prefill={prefill} onCancel={() => { setMode("list"); setPrefill(null); }} onSave={handleSave} />;
  }
  if (mode === "interval" && active) {
    return <IntervalRunner workout={active} onExit={() => setMode("list")} />;
  }

  const weekDays = Array.from({ length: 7 }, (_, i) => { const d = new Date(weekStart); d.setDate(d.getDate() + i); return d; });
  const weekdayLabels = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

  const workoutsOnDay = (day) => workouts.filter((w) => w.loggedAt && sameDay(new Date(w.loggedAt), day));
  const dayWorkouts = workoutsOnDay(selectedDay);

  const shiftWeek = (dir) => {
    const newStart = new Date(weekStart); newStart.setDate(newStart.getDate() + dir * 7);
    const newSelected = new Date(selectedDay); newSelected.setDate(newSelected.getDate() + dir * 7);
    setWeekStart(newStart); setSelectedDay(newSelected);
  };

  const chartData = weekDays.map((d, i) => {
    const sessions = workoutsOnDay(d);
    return {
      day: weekdayLabels[i],
      minutes: sessions.reduce((s, w) => s + (w.duration || 0), 0),
      isSelected: sameDay(d, selectedDay),
    };
  });

  const weekTotals = chartData.reduce((s, d) => ({ minutes: s.minutes + d.minutes, sessions: s.sessions + (d.minutes > 0 ? 1 : 0) }), { minutes: 0, sessions: 0 });

  return (
    <div>
      <SectionHeader title="Training" action={<AddButton onClick={openNew} label="Build session" />} />

      <Card>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
          <span style={{ fontFamily: FONT_BODY, fontSize: 11, color: C.textMuted }}>
            {weekDays[0].toLocaleDateString([], { month: "short", day: "numeric" })} – {weekDays[6].toLocaleDateString([], { month: "short", day: "numeric" })}
          </span>
          <div style={{ display: "flex", gap: 2 }}>
            <IconButton onClick={() => shiftWeek(-1)} color={C.textSecondary}><ChevronLeft size={16} /></IconButton>
            <IconButton onClick={() => shiftWeek(1)} color={C.textSecondary}><ChevronRight size={16} /></IconButton>
          </div>
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(7,1fr)", gap: 4 }}>
          {weekDays.map((d, i) => {
            const has = workoutsOnDay(d).length > 0;
            const isSelected = sameDay(d, selectedDay);
            const isToday = sameDay(d, today);
            return (
              <button key={i} onClick={() => setSelectedDay(d)} style={{
                border: "none", borderRadius: 8, cursor: "pointer", padding: "6px 0",
                background: isSelected ? C.teal : has ? C.tealDim : "transparent",
                outline: isToday && !isSelected ? `1px solid ${C.outline}` : "none",
                display: "flex", flexDirection: "column", alignItems: "center", gap: 3,
              }}>
                <span style={{ fontFamily: FONT_BODY, fontSize: 9.5, color: isSelected ? C.bg : C.textMuted, textTransform: "uppercase" }}>{weekdayLabels[i]}</span>
                <span style={{ fontFamily: FONT_DISPLAY, fontSize: 13, color: isSelected ? C.bg : C.textPrimary }}>{d.getDate()}</span>
              </button>
            );
          })}
        </div>
      </Card>

      <SectionHeader title={sameDay(selectedDay, today) ? "Today" : selectedDay.toLocaleDateString([], { weekday: "long", month: "short", day: "numeric" })} />
      {dayWorkouts.length > 0 ? (
        dayWorkouts.map((w) => (
          <Card key={w.id}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
              <div>
                <span style={{ fontFamily: FONT_BODY, fontSize: 13, color: C.textPrimary, fontWeight: 600 }}>{w.name}</span>
                <div style={{ fontFamily: FONT_BODY, fontSize: 11, color: C.textSecondary, marginTop: 2 }}>
                  {w.type} · {w.duration} min{w.calories ? ` · ${w.calories} kcal` : ""}
                </div>
                {w.injuryLabel && (
                  <div style={{ display: "inline-flex", alignItems: "center", gap: 3, marginTop: 4, background: C.coralDim, borderRadius: 5, padding: "1px 6px" }}>
                    <AlertCircle size={9} color={C.coral} />
                    <span style={{ fontFamily: FONT_BODY, fontSize: 9, color: C.coral }}>For: {w.injuryLabel}</span>
                  </div>
                )}
              </div>
              <div style={{ display: "flex", gap: 2 }}>
                {w.type === "Cardio" && w.intervals && (
                  <IconButton onClick={() => openInterval(w)} color={C.teal}><PlayCircle size={17} /></IconButton>
                )}
                <IconButton onClick={() => openEdit(w)} color={C.textSecondary}><Pencil size={15} /></IconButton>
                <IconButton onClick={() => setConfirmId(w.id)} color={C.coral}><Trash2 size={15} /></IconButton>
              </div>
            </div>
            {w.blocks?.length > 0 && (
              <div style={{ marginTop: 8, borderTop: `1px solid ${C.border}`, paddingTop: 8 }}>
                {w.blocks.map((bl, i) => (
                  <div key={bl.id} style={{ marginBottom: 4 }}>
                    <div style={{ fontFamily: FONT_BODY, fontSize: 10, color: C.teal, textTransform: "uppercase", letterSpacing: 0.3 }}>
                      Block {blockLabel(i)}{bl.name ? ` · ${bl.name}` : ""}
                    </div>
                    {bl.exercises.map((ex) => (
                      <div key={ex.id} style={{ display: "flex", justifyContent: "space-between", fontFamily: FONT_DISPLAY, fontSize: 11, color: C.textSecondary, padding: "2px 0" }}>
                        <span>{ex.name}</span>
                        <span>{ex.sets}x{ex.reps} @ {ex.load}kg · {ex.rest}s rest</span>
                      </div>
                    ))}
                  </div>
                ))}
              </div>
            )}
          </Card>
        ))
      ) : (
        <Card><span style={{ fontFamily: FONT_BODY, fontSize: 12, color: C.textMuted }}>Nothing logged this day.</span></Card>
      )}

      <SectionHeader title="Performance this week" />
      <Card>
        <div style={{ display: "flex", gap: 16, marginBottom: 6 }}>
          <div>
            <div style={{ fontFamily: FONT_DISPLAY, fontSize: 16, color: C.textPrimary }}>{weekTotals.sessions}</div>
            <div style={{ fontFamily: FONT_BODY, fontSize: 9.5, color: C.textMuted, textTransform: "uppercase" }}>Sessions</div>
          </div>
          <div>
            <div style={{ fontFamily: FONT_DISPLAY, fontSize: 16, color: C.textPrimary }}>{weekTotals.minutes}</div>
            <div style={{ fontFamily: FONT_BODY, fontSize: 9.5, color: C.textMuted, textTransform: "uppercase" }}>Minutes</div>
          </div>
        </div>
        <ResponsiveContainer width="100%" height={140}>
          <BarChart data={chartData} margin={{ top: 4, right: 4, left: -20, bottom: 0 }}>
            <CartesianGrid strokeDasharray="3 3" stroke={C.border} vertical={false} />
            <XAxis dataKey="day" tick={{ fontFamily: FONT_BODY, fontSize: 10, fill: C.textMuted }} axisLine={{ stroke: C.border }} tickLine={false} />
            <YAxis tick={{ fontFamily: FONT_BODY, fontSize: 10, fill: C.textMuted }} axisLine={false} tickLine={false} />
            <Tooltip contentStyle={{ background: C.surfaceRaised, border: `1px solid ${C.outline}`, borderRadius: 8, fontFamily: FONT_BODY, fontSize: 12 }} />
            <Bar dataKey="minutes" name="Minutes" radius={[4, 4, 0, 0]}>
              {chartData.map((d, i) => <Cell key={i} fill={d.isSelected ? C.teal : C.tealDim} />)}
            </Bar>
          </BarChart>
        </ResponsiveContainer>
      </Card>

      {confirmId && (
        <ConfirmDelete label="session" onCancel={() => setConfirmId(null)} onConfirm={() => { removeWorkout(confirmId); setConfirmId(null); }} />
      )}
    </div>
  );
}

// ---- food search: instant local database + AI estimate fallback ----
// Open Food Facts — free public food database. Blocked by Claude.ai's artifact sandbox
// (which only allows fetch to a small allowlist), so this call will fail with a
// network/CORS-style error inside a Claude.ai preview. Once this app is extracted and
// deployed on your own domain or as a native app, this same function works as-is —
// no changes needed. Docs: https://world.openfoodfacts.org/data
async function searchOpenFoodFacts(query) {
  const url = `https://world.openfoodfacts.org/cgi/search.pl?search_terms=${encodeURIComponent(query)}&search_simple=1&action=process&json=1&page_size=8&fields=product_name,nutriments`;
  const res = await fetch(url);
  if (!res.ok) throw new Error(`Open Food Facts responded ${res.status}`);
  const data = await res.json();
  return (data.products || [])
    .filter((p) => p.product_name && p.nutriments && p.nutriments["energy-kcal_100g"] != null)
    .slice(0, 6)
    .map((p) => ({
      name: `${p.product_name} (per 100g)`,
      cals: Math.round(p.nutriments["energy-kcal_100g"] || 0),
      protein: Math.round(p.nutriments["proteins_100g"] || 0),
      carbs: Math.round(p.nutriments["carbohydrates_100g"] || 0),
      fat: Math.round(p.nutriments["fat_100g"] || 0),
    }));
}

function FoodSearchInput({ value, onChange, onSelect, customFoods, onSaveCustomFood }) {
  const [showList, setShowList] = useState(false);
  const [aiLoading, setAiLoading] = useState(false);
  const [aiError, setAiError] = useState(false);
  const [offLoading, setOffLoading] = useState(false);
  const [offError, setOffError] = useState(false);
  const [offResults, setOffResults] = useState(null);

  const suggestions = localFoodSearch(value, customFoods);

  const askAI = async () => {
    setAiLoading(true); setAiError(false);
    try {
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-6",
          max_tokens: 200,
          messages: [{
            role: "user",
            content: `Give a typical nutrition estimate for one standard serving of: "${value}". Respond with ONLY a JSON object, no markdown, no extra text, in this exact shape: {"name": "short label with serving size", "cals": number, "protein": number, "carbs": number, "fat": number}`,
          }],
        }),
      });
      const data = await res.json();
      const text = (data.content || []).map((b) => b.text || "").join("").trim();
      const cleaned = text.replace(/```json|```/g, "").trim();
      const parsed = JSON.parse(cleaned);
      const food = { name: parsed.name || value, cals: Number(parsed.cals) || 0, protein: Number(parsed.protein) || 0, carbs: Number(parsed.carbs) || 0, fat: Number(parsed.fat) || 0 };
      onSelect(food);
      if (onSaveCustomFood) onSaveCustomFood(food);
      setShowList(false);
    } catch (e) {
      setAiError(true);
    } finally {
      setAiLoading(false);
    }
  };

  const askOFF = async () => {
    setOffLoading(true); setOffError(false); setOffResults(null);
    try {
      const results = await searchOpenFoodFacts(value);
      if (results.length === 0) { setOffError(true); return; }
      setOffResults(results);
    } catch (e) {
      setOffError(true);
    } finally {
      setOffLoading(false);
    }
  };


  return (
    <div style={{ position: "relative" }}>
      <div style={{ position: "relative" }}>
        <Search size={13} color={C.textMuted} style={{ position: "absolute", left: 10, top: 11 }} />
        <input
          style={{ ...inputStyle, paddingLeft: 30 }}
          value={value}
          onChange={(e) => { onChange(e.target.value); setShowList(true); setAiError(false); }}
          onFocus={() => setShowList(true)}
          onBlur={() => setTimeout(() => setShowList(false), 180)}
          placeholder="Search a food, e.g. banana"
        />
      </div>
      {showList && value.trim().length >= 2 && (
        <div style={{
          position: "absolute", top: "100%", left: 0, right: 0, marginTop: 4, background: C.surfaceRaised,
          border: `1px solid ${C.outline}`, borderRadius: 8, zIndex: 30, maxHeight: 230, overflowY: "auto",
        }}>
          {suggestions.map((p, i) => (
            <div key={i} onMouseDown={() => { onSelect(p); setShowList(false); }} style={{
              padding: "8px 10px", cursor: "pointer", borderBottom: `1px solid ${C.border}`,
            }}>
              <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                <span style={{ fontFamily: FONT_BODY, fontSize: 12, color: C.textPrimary }}>{p.name}</span>
                {p.custom && (
                  <span style={{ fontFamily: FONT_BODY, fontSize: 8.5, textTransform: "uppercase", color: C.teal, background: C.tealDim, padding: "1px 5px", borderRadius: 4 }}>Saved</span>
                )}
              </div>
              <div style={{ fontFamily: FONT_DISPLAY, fontSize: 10, color: C.textMuted, marginTop: 1 }}>
                {p.cals} kcal · P{p.protein} C{p.carbs} F{p.fat}
              </div>
            </div>
          ))}
          <div onMouseDown={(e) => e.preventDefault()} onClick={askAI} style={{
            padding: "9px 10px", cursor: "pointer", display: "flex", alignItems: "center", gap: 6, borderBottom: `1px solid ${C.border}`,
          }}>
            {aiLoading ? <Loader2 size={13} color={C.teal} style={{ animation: "cmh-spin 0.8s linear infinite" }} /> : <Sparkles size={13} color={C.teal} />}
            <span style={{ fontFamily: FONT_BODY, fontSize: 12, color: C.teal }}>
              {aiLoading ? "Estimating..." : `Not listed — get an AI estimate for "${value}"`}
            </span>
          </div>
          {aiError && <div style={{ padding: "0 10px 9px", fontFamily: FONT_BODY, fontSize: 10.5, color: C.coral, borderBottom: `1px solid ${C.border}` }}>AI estimate unavailable right now — try again or enter values manually.</div>}

          <div onMouseDown={(e) => e.preventDefault()} onClick={askOFF} style={{
            padding: "9px 10px", cursor: "pointer", display: "flex", alignItems: "center", gap: 6,
          }}>
            {offLoading ? <Loader2 size={13} color={C.textSecondary} style={{ animation: "cmh-spin 0.8s linear infinite" }} /> : <Search size={13} color={C.textSecondary} />}
            <span style={{ fontFamily: FONT_BODY, fontSize: 12, color: C.textSecondary }}>
              {offLoading ? "Searching Open Food Facts..." : `Search Open Food Facts online for "${value}"`}
            </span>
          </div>
          {offResults && offResults.map((p, i) => (
            <div key={i} onMouseDown={() => { onSelect(p); setShowList(false); setOffResults(null); }} style={{
              padding: "8px 10px", cursor: "pointer", borderTop: `1px solid ${C.border}`,
            }}>
              <div style={{ fontFamily: FONT_BODY, fontSize: 12, color: C.textPrimary }}>{p.name}</div>
              <div style={{ fontFamily: FONT_DISPLAY, fontSize: 10, color: C.textMuted, marginTop: 1 }}>
                {p.cals} kcal · P{p.protein} C{p.carbs} F{p.fat}
              </div>
            </div>
          ))}
          {offError && (
            <div style={{ padding: "0 10px 9px", fontFamily: FONT_BODY, fontSize: 10.5, color: C.textMuted }}>
              Can't reach Open Food Facts from inside this preview — Claude.ai's sandbox blocks calls to outside sites.
              This same code will work once the app is running on its own domain or as a native app.
            </div>
          )}
        </div>
      )}
      <style>{`@keyframes cmh-spin { to { transform: rotate(360deg); } }`}</style>
    </div>
  );
}

function FuelTab({ meals, addMeal, removeMeal, customFoods, addCustomFood }) {
  const [open, setOpen] = useState(false);
  const [confirmId, setConfirmId] = useState(null);
  const [name, setName] = useState("");
  const [cals, setCals] = useState("");
  const [protein, setProtein] = useState("");
  const [carbs, setCarbs] = useState("");
  const [fat, setFat] = useState("");
  const [servings, setServings] = useState("1");
  const [base, setBase] = useState(null); // per-serving values from the selected food, for scaling

  const recentFoods = React.useMemo(() => {
    const seen = new Set();
    const out = [];
    for (const m of meals) {
      const key = m.name.toLowerCase();
      if (seen.has(key)) continue;
      seen.add(key);
      out.push(m);
      if (out.length >= 6) break;
    }
    return out;
  }, [meals]);

  const applyServings = (n, b) => {
    const s = Number(n) || 0;
    const src = b || base;
    if (!src) return;
    setCals(String(Math.round(src.cals * s)));
    setProtein(String(Math.round(src.protein * s)));
    setCarbs(String(Math.round(src.carbs * s)));
    setFat(String(Math.round(src.fat * s)));
  };

  const selectFood = (p) => {
    setName(p.name);
    setBase({ cals: p.cals, protein: p.protein, carbs: p.carbs, fat: p.fat });
    setServings("1");
    setCals(String(p.cals)); setProtein(String(p.protein)); setCarbs(String(p.carbs)); setFat(String(p.fat));
  };

  const quickAddRecent = (m) => {
    setName(m.name); setCals(String(m.cals)); setProtein(String(m.protein)); setCarbs(String(m.carbs)); setFat(String(m.fat));
    setBase({ cals: m.cals, protein: m.protein, carbs: m.carbs, fat: m.fat }); setServings("1");
  };

  const submit = () => {
    if (!name.trim()) return;
    addMeal({
      id: uid(), name, time: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
      cals: Number(cals) || 0, protein: Number(protein) || 0, carbs: Number(carbs) || 0, fat: Number(fat) || 0,
      loggedAt: new Date().toISOString(),
    });
    setName(""); setCals(""); setProtein(""); setCarbs(""); setFat(""); setServings("1"); setBase(null); setOpen(false);
  };

  return (
    <div>
      <SectionHeader title="Fuel log" action={<AddButton onClick={() => setOpen(true)} label="Add meal" />} />
      <MacrosWidget meals={meals} />
      {meals.map((m) => (
        <Card key={m.id}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
            <div>
              <span style={{ fontFamily: FONT_BODY, fontSize: 13, color: C.textPrimary }}>{m.name}</span>
              <div style={{ fontFamily: FONT_DISPLAY, fontSize: 11, color: C.textSecondary, marginTop: 3 }}>
                {m.cals} kcal · P{m.protein} C{m.carbs} F{m.fat}
              </div>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <span style={{ fontFamily: FONT_BODY, fontSize: 11, color: C.textMuted }}>{m.time}</span>
              <IconButton onClick={() => setConfirmId(m.id)} color={C.coral}><Trash2 size={14} /></IconButton>
            </div>
          </div>
        </Card>
      ))}
      {open && (
        <Modal title="Add a meal" onClose={() => setOpen(false)}>
          {recentFoods.length > 0 && (
            <div style={{ marginBottom: 12 }}>
              <span style={{ fontFamily: FONT_BODY, fontSize: 10, color: C.textMuted, textTransform: "uppercase", letterSpacing: 0.3 }}>Recent</span>
              <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 5 }}>
                {recentFoods.map((m) => (
                  <button key={m.id} onClick={() => quickAddRecent(m)} style={{
                    background: C.surfaceRaised, border: `1px solid ${C.border}`, borderRadius: 14,
                    padding: "5px 10px", fontFamily: FONT_BODY, fontSize: 11, color: C.textSecondary, cursor: "pointer",
                  }}>{m.name}</button>
                ))}
              </div>
            </div>
          )}
          <Field label="Meal">
            <FoodSearchInput
              value={name}
              onChange={(v) => { setName(v); setBase(null); }}
              onSelect={selectFood}
              customFoods={customFoods}
              onSaveCustomFood={addCustomFood}
            />
          </Field>
          <p style={{ fontFamily: FONT_BODY, fontSize: 10.5, color: C.textMuted, marginTop: -6, marginBottom: 10 }}>
            Searches your saved foods and a built-in list instantly. AI estimate works right here; Open Food Facts activates once this app is deployed outside Claude.ai.
          </p>
          {base && (
            <Field label="Servings">
              <input style={inputStyle} type="number" step="0.5" min="0" value={servings}
                onChange={(e) => { setServings(e.target.value); applyServings(e.target.value); }} />
            </Field>
          )}
          <Field label="Calories"><input style={inputStyle} type="number" value={cals} onChange={(e) => setCals(e.target.value)} placeholder="550" /></Field>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 8 }}>
            <Field label="Protein"><input style={inputStyle} type="number" value={protein} onChange={(e) => setProtein(e.target.value)} placeholder="40" /></Field>
            <Field label="Carbs"><input style={inputStyle} type="number" value={carbs} onChange={(e) => setCarbs(e.target.value)} placeholder="50" /></Field>
            <Field label="Fat"><input style={inputStyle} type="number" value={fat} onChange={(e) => setFat(e.target.value)} placeholder="18" /></Field>
          </div>
          <PrimaryButton onClick={submit}>Save meal</PrimaryButton>
        </Modal>
      )}
      {confirmId && <ConfirmDelete label="meal" onCancel={() => setConfirmId(null)} onConfirm={() => { removeMeal(confirmId); setConfirmId(null); }} />}
    </div>
  );
}

function MedsTab({ meds, addMed, toggleTaken, removeMed, restockMed, pendingLink, clearPendingLink }) {
  const [open, setOpen] = useState(false);
  const [confirmId, setConfirmId] = useState(null);
  const [restockId, setRestockId] = useState(null);
  const [restockAmount, setRestockAmount] = useState("30");
  const [name, setName] = useState("");
  const [dose, setDose] = useState("");
  const [freq, setFreq] = useState("");
  const [category, setCategory] = useState("Supplement");
  const [stock, setStock] = useState("");
  const [lowStockAt, setLowStockAt] = useState("");
  const [refillDate, setRefillDate] = useState("");
  const [linkedInjury, setLinkedInjury] = useState(null);

  useEffect(() => {
    if (pendingLink && pendingLink.type === "med") {
      setLinkedInjury({ id: pendingLink.injuryId, label: pendingLink.injuryLabel });
      setOpen(true);
      clearPendingLink();
    }
  }, [pendingLink]);

  const submit = () => {
    if (!name.trim()) return;
    addMed({
      id: uid(), name, dose, freq, category, takenToday: false,
      stock: stock !== "" ? Number(stock) : null,
      lowStockAt: lowStockAt !== "" ? Number(lowStockAt) : null,
      refillDate: refillDate ? new Date(refillDate).toISOString() : null,
      injuryId: linkedInjury ? linkedInjury.id : null,
      injuryLabel: linkedInjury ? linkedInjury.label : null,
    });
    setName(""); setDose(""); setFreq(""); setStock(""); setLowStockAt(""); setRefillDate(""); setOpen(false); setLinkedInjury(null);
  };

  const today = new Date();

  return (
    <div>
      <SectionHeader title="Protocol" action={<AddButton onClick={() => { setLinkedInjury(null); setOpen(true); }} label="Add item" />} />
      {meds.map((m) => {
        const isLow = m.stock != null && m.lowStockAt != null && m.stock <= m.lowStockAt;
        const refillDue = m.refillDate && new Date(m.refillDate) <= today;
        return (
          <Card key={m.id}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div>
                <div style={{ display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap" }}>
                  <span style={{ fontFamily: FONT_BODY, fontSize: 13, color: C.textPrimary, fontWeight: 600 }}>{m.name}</span>
                  <span style={{
                    fontFamily: FONT_BODY, fontSize: 9, textTransform: "uppercase", letterSpacing: 0.3,
                    color: m.category === "Peptide" ? C.amber : C.textMuted,
                    background: m.category === "Peptide" ? C.amberDim : C.surfaceRaised,
                    padding: "2px 6px", borderRadius: 5,
                  }}>{m.category}</span>
                </div>
                <div style={{ fontFamily: FONT_DISPLAY, fontSize: 11, color: C.textSecondary, marginTop: 3 }}>{m.dose} · {m.freq}</div>
                {m.injuryLabel && (
                  <div style={{ display: "inline-flex", alignItems: "center", gap: 3, marginTop: 4, background: C.coralDim, borderRadius: 5, padding: "1px 6px" }}>
                    <AlertCircle size={9} color={C.coral} />
                    <span style={{ fontFamily: FONT_BODY, fontSize: 9, color: C.coral }}>For: {m.injuryLabel}</span>
                  </div>
                )}
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                <IconButton onClick={() => setConfirmId(m.id)} color={C.coral}><Trash2 size={14} /></IconButton>
                <button onClick={() => toggleTaken(m.id)} style={{
                  width: 30, height: 30, borderRadius: "50%", border: `1px solid ${m.takenToday ? C.teal : C.borderStrong}`,
                  background: m.takenToday ? C.tealDim : "transparent", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer",
                }}>
                  <Check size={14} color={m.takenToday ? C.teal : C.textMuted} />
                </button>
              </div>
            </div>

            {(m.stock != null || m.refillDate) && (
              <div style={{ marginTop: 8, paddingTop: 8, borderTop: `1px solid ${C.border}`, display: "flex", alignItems: "center", justifyContent: "space-between", flexWrap: "wrap", gap: 6 }}>
                <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
                  {m.stock != null && (
                    <span style={{ display: "flex", alignItems: "center", gap: 4, fontFamily: FONT_DISPLAY, fontSize: 11, color: isLow ? C.coral : C.textSecondary }}>
                      <Package size={12} /> {m.stock} left
                    </span>
                  )}
                  {isLow && (
                    <span style={{ fontFamily: FONT_BODY, fontSize: 9, textTransform: "uppercase", letterSpacing: 0.3, color: C.coral, background: C.coralDim, padding: "2px 6px", borderRadius: 5 }}>
                      Refill soon
                    </span>
                  )}
                  {m.refillDate && (
                    <span style={{ display: "flex", alignItems: "center", gap: 4, fontFamily: FONT_BODY, fontSize: 10, color: refillDue ? C.coral : C.textMuted }}>
                      <BellRing size={11} /> {refillDue ? "Refill due" : "Refill by"} {new Date(m.refillDate).toLocaleDateString([], { month: "short", day: "numeric" })}
                    </span>
                  )}
                </div>
                {m.stock != null && (
                  <button onClick={() => { setRestockId(m.id); setRestockAmount("30"); }} style={{
                    background: "transparent", border: `1px solid ${C.outline}`, color: C.teal, borderRadius: 7,
                    padding: "3px 8px", fontFamily: FONT_BODY, fontSize: 10.5, cursor: "pointer",
                  }}>Restock</button>
                )}
              </div>
            )}
          </Card>
        );
      })}
      {open && (
        <Modal title="Add to protocol" onClose={() => setOpen(false)}>
          {linkedInjury && (
            <div style={{ display: "flex", alignItems: "center", gap: 6, background: C.coralDim, borderRadius: 8, padding: "7px 10px", marginBottom: 10 }}>
              <AlertCircle size={13} color={C.coral} />
              <span style={{ fontFamily: FONT_BODY, fontSize: 11, color: C.coral }}>Linked to recovery from: {linkedInjury.label}</span>
            </div>
          )}
          <Field label="Name"><input style={inputStyle} value={name} onChange={(e) => setName(e.target.value)} placeholder="TB-500, Magnesium..." /></Field>
          <Field label="Dose"><input style={inputStyle} value={dose} onChange={(e) => setDose(e.target.value)} placeholder="250 mcg" /></Field>
          <Field label="Frequency"><input style={inputStyle} value={freq} onChange={(e) => setFreq(e.target.value)} placeholder="Daily, AM" /></Field>
          <Field label="Category">
            <select style={inputStyle} value={category} onChange={(e) => setCategory(e.target.value)}>
              <option>Supplement</option><option>Peptide</option><option>Medication</option>
            </select>
          </Field>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
            <Field label="Current stock (optional)"><input style={inputStyle} type="number" value={stock} onChange={(e) => setStock(e.target.value)} placeholder="30" /></Field>
            <Field label="Low stock alert at"><input style={inputStyle} type="number" value={lowStockAt} onChange={(e) => setLowStockAt(e.target.value)} placeholder="5" /></Field>
          </div>
          <Field label="Refill reminder date (optional)"><input style={inputStyle} type="date" value={refillDate} onChange={(e) => setRefillDate(e.target.value)} /></Field>
          <p style={{ fontFamily: FONT_BODY, fontSize: 10.5, color: C.textMuted, marginTop: -6 }}>
            Stock counts down each time you check this off as taken. You'll see a "Refill soon" flag once it drops to your alert level.
          </p>
          <PrimaryButton onClick={submit}>Save</PrimaryButton>
        </Modal>
      )}
      {restockId && (
        <Modal title="Restock" onClose={() => setRestockId(null)}>
          <Field label="Add quantity"><input style={inputStyle} type="number" value={restockAmount} onChange={(e) => setRestockAmount(e.target.value)} /></Field>
          <PrimaryButton onClick={() => { restockMed(restockId, Number(restockAmount) || 0); setRestockId(null); }}>Add to stock</PrimaryButton>
        </Modal>
      )}
      {confirmId && <ConfirmDelete label="protocol item" onCancel={() => setConfirmId(null)} onConfirm={() => { removeMed(confirmId); setConfirmId(null); }} />}
    </div>
  );
}

// ---- uploaded scan document viewer ----
function ScanDocCard({ doc, onRemove, onSaveExtracted }) {
  const [expanded, setExpanded] = useState(false);
  const [extracting, setExtracting] = useState(false);
  const [extractError, setExtractError] = useState(false);
  const [extractErrorDetail, setExtractErrorDetail] = useState("");
  const [found, setFound] = useState(null); // array of {marker, value, unit, checked}
  const [saveCategory, setSaveCategory] = useState("Body Composition");

  const readData = async () => {
    setExtracting(true); setExtractError(false); setFound(null); setExtractErrorDetail("");
    try {
      const base64Only = doc.dataUrl.split(",")[1];
      const blockType = doc.type === "application/pdf" ? "document" : "image";
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-6",
          max_tokens: 1000,
          messages: [{
            role: "user",
            content: [
              { type: blockType, source: { type: "base64", media_type: doc.type, data: base64Only } },
              {
                type: "text",
                text: "This is a scan report or lab result document (e.g. a body composition analyzer printout or bloodwork panel). Extract every distinct labeled numeric measurement you can find. Respond with ONLY a JSON array, no markdown, no extra text, in this exact shape: [{\"marker\": \"short clear label\", \"value\": number, \"unit\": \"unit or empty string\"}]. Skip narrative/explanatory text and reference ranges — only the person's actual measured values.",
              },
            ],
          }],
        }),
      });
      const data = await res.json();
      if (!res.ok) {
        const msg = (data && data.error && data.error.message) || `Request failed (${res.status})`;
        console.error("Scan read error:", data);
        setExtractErrorDetail(msg);
        setExtractError(true);
        return;
      }
      const text = (data.content || []).map((b) => b.text || "").join("").trim();
      let cleaned = text.replace(/```json|```/g, "").trim();
      // Claude occasionally adds a short lead-in despite instructions — pull out the array if so
      const arrayMatch = cleaned.match(/\[[\s\S]*\]/);
      if (arrayMatch) cleaned = arrayMatch[0];
      let parsed;
      try {
        parsed = JSON.parse(cleaned);
      } catch (parseErr) {
        console.error("Scan read: could not parse response", text);
        setExtractErrorDetail("Got a response but couldn't parse it as data.");
        setExtractError(true);
        return;
      }
      if (!Array.isArray(parsed) || parsed.length === 0) {
        setExtractErrorDetail("No measurements found in this file.");
        setExtractError(true);
        return;
      }
      setFound(parsed.map((f) => ({ marker: f.marker, value: Number(f.value) || 0, unit: f.unit || "", checked: true })));
    } catch (e) {
      console.error("Scan read error:", e);
      setExtractErrorDetail(e && e.message ? e.message : "Network error.");
      setExtractError(true);
    } finally {
      setExtracting(false);
    }
  };

  const toggleFound = (i) => setFound((prev) => prev.map((f, idx) => (idx === i ? { ...f, checked: !f.checked } : f)));

  const saveChecked = () => {
    const selected = found.filter((f) => f.checked);
    onSaveExtracted(selected, saveCategory);
    setFound(null);
  };

  return (
    <Card>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, minWidth: 0 }}>
          <FileText size={15} color={C.teal} style={{ flexShrink: 0 }} />
          <div style={{ minWidth: 0 }}>
            <div style={{ fontFamily: FONT_BODY, fontSize: 12, color: C.textPrimary, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{doc.name}</div>
            <div style={{ fontFamily: FONT_BODY, fontSize: 10, color: C.textMuted, marginTop: 1 }}>{doc.uploadedAt}</div>
          </div>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 4, flexShrink: 0 }}>
          <IconButton onClick={() => setExpanded((e) => !e)} color={C.textSecondary}>
            {expanded ? <Minimize2 size={14} /> : <Maximize2 size={14} />}
          </IconButton>
          <IconButton onClick={onRemove} color={C.coral}><Trash2 size={14} /></IconButton>
        </div>
      </div>

      <div onClick={readData} style={{
        display: "flex", alignItems: "center", gap: 6, cursor: "pointer", marginTop: 9,
        padding: "7px 10px", background: C.tealDim, borderRadius: 7,
      }}>
        {extracting ? <Loader2 size={13} color={C.teal} style={{ animation: "cmh-spin 0.8s linear infinite" }} /> : <Sparkles size={13} color={C.teal} />}
        <span style={{ fontFamily: FONT_BODY, fontSize: 12, color: C.teal }}>
          {extracting ? "Reading document..." : "Read data from this file"}
        </span>
      </div>
      {extractError && (
        <div style={{ fontFamily: FONT_BODY, fontSize: 10.5, color: C.coral, marginTop: 6 }}>
          Couldn't read this file{extractErrorDetail ? `: ${extractErrorDetail}` : "."} Try the manual "Log scan" form instead.
        </div>
      )}

      {found && (
        <div style={{ marginTop: 10, border: `1px solid ${C.outline}`, borderRadius: 8, padding: 10 }}>
          <div style={{ fontFamily: FONT_BODY, fontSize: 11, color: C.textSecondary, marginBottom: 6 }}>Found in this document — review before saving:</div>
          {found.map((f, i) => (
            <label key={i} style={{ display: "flex", alignItems: "center", gap: 8, padding: "4px 0", cursor: "pointer" }}>
              <input type="checkbox" checked={f.checked} onChange={() => toggleFound(i)} style={{ accentColor: C.teal, width: 14, height: 14, flexShrink: 0 }} />
              <span style={{ fontFamily: FONT_BODY, fontSize: 12, color: C.textPrimary, flex: 1 }}>{f.marker}</span>
              <span style={{ fontFamily: FONT_DISPLAY, fontSize: 12, color: C.textSecondary }}>{f.value} {f.unit}</span>
            </label>
          ))}
          <div style={{ display: "flex", gap: 8, alignItems: "center", marginTop: 8 }}>
            <select style={{ ...miniInputStyle, flex: 1 }} value={saveCategory} onChange={(e) => setSaveCategory(e.target.value)}>
              <option value="Body Composition">Save as Body Composition</option>
              <option value="Bloodwork">Save as Bloodwork</option>
            </select>
          </div>
          <PrimaryButton onClick={saveChecked}>Save selected to Labs</PrimaryButton>
        </div>
      )}

      {expanded && (
        <div style={{ marginTop: 10, borderRadius: 8, overflow: "hidden", border: `1px solid ${C.border}` }}>
          {doc.type === "application/pdf" ? (
            <embed src={doc.dataUrl} type="application/pdf" width="100%" height="480" style={{ display: "block" }} />
          ) : (
            <img src={doc.dataUrl} alt={doc.name} style={{ width: "100%", display: "block" }} />
          )}
          <div style={{ padding: "6px 8px", background: C.surfaceRaised, textAlign: "center" }}>
            <a href={doc.dataUrl} download={doc.name} style={{ fontFamily: FONT_BODY, fontSize: 11, color: C.teal, textDecoration: "none" }}>
              Open full size / download
            </a>
          </div>
        </div>
      )}
    </Card>
  );
}

// ---- Renpho smart scale sync (unofficial, direct) ----
// Talks to /api/renpho-latest — a serverless function that only exists once
// this app is deployed with a real backend (see api/ folder + README).
// Inside the Claude.ai preview this call will fail gracefully with an explanation.
function RenphoSyncCard({ addLab }) {
  const [syncing, setSyncing] = useState(false);
  const [error, setError] = useState("");
  const [readings, setReadings] = useState(null); // pending review before saving
  const [measuredAt, setMeasuredAt] = useState(null);

  const FIELD_LABELS = {
    weight: { marker: "Weight", unit: "kg" },
    bmi: { marker: "BMI", unit: "" },
    skeletalMuscleMass: { marker: "Skeletal Muscle Mass", unit: "kg" },
    bodyFat: { marker: "Body Fat", unit: "%" },
    visceralFat: { marker: "Visceral Fat Rating", unit: "" },
    bodyWater: { marker: "Body Water", unit: "%" },
  };

  const sync = async () => {
    setSyncing(true); setError(""); setReadings(null);
    try {
      const res = await fetch("/api/renpho-latest");
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || `Request failed (${res.status})`);
      const rows = Object.entries(FIELD_LABELS)
        .filter(([key]) => data[key] != null)
        .map(([key, meta]) => ({ marker: meta.marker, value: data[key], unit: meta.unit, checked: true }));
      if (rows.length === 0) { setError("Connected, but no readable measurements came back."); return; }
      setReadings(rows);
      setMeasuredAt(data.measuredAt || null);
    } catch (e) {
      setError(e.message || "Couldn't reach the backend. This needs the app deployed with its /api functions — see the README.");
    } finally {
      setSyncing(false);
    }
  };

  const toggleReading = (i) => setReadings((prev) => prev.map((r, idx) => (idx === i ? { ...r, checked: !r.checked } : r)));

  const saveReadings = () => {
    const today = new Date().toLocaleDateString([], { month: "short", day: "numeric" });
    readings.filter((r) => r.checked).forEach((r) => {
      addLab({ id: uid(), marker: r.marker, value: r.value, unit: r.unit, range: "", flag: "normal", date: today, category: "Body Composition" });
    });
    setReadings(null);
  };

  return (
    <Card>
      <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
        <Scan size={15} color={C.teal} />
        <span style={{ fontFamily: FONT_BODY, fontSize: 13, color: C.textPrimary, fontWeight: 600 }}>Renpho Smart Scale</span>
      </div>
      <p style={{ fontFamily: FONT_BODY, fontSize: 10.5, color: C.textMuted, margin: "4px 0 10px" }}>
        Unofficial community integration — reads your latest weigh-in directly from your Renpho account.
        Requires this app to be deployed with its backend and your Renpho login stored there — won't work
        inside this preview. See the README before setting this up.
      </p>

      <PrimaryButton onClick={sync}>{syncing ? "Syncing..." : "Sync latest reading"}</PrimaryButton>

      {error && <p style={{ fontFamily: FONT_BODY, fontSize: 10.5, color: C.coral, marginTop: 8 }}>{error}</p>}

      {readings && (
        <div style={{ marginTop: 10, border: `1px solid ${C.outline}`, borderRadius: 8, padding: 10 }}>
          <div style={{ fontFamily: FONT_BODY, fontSize: 11, color: C.textSecondary, marginBottom: 6 }}>
            From your scale{measuredAt ? `, ${new Date(measuredAt).toLocaleDateString([], { month: "short", day: "numeric" })}` : ""} — review before saving:
          </div>
          {readings.map((r, i) => (
            <label key={i} style={{ display: "flex", alignItems: "center", gap: 8, padding: "4px 0", cursor: "pointer" }}>
              <input type="checkbox" checked={r.checked} onChange={() => toggleReading(i)} style={{ accentColor: C.teal, width: 14, height: 14, flexShrink: 0 }} />
              <span style={{ fontFamily: FONT_BODY, fontSize: 12, color: C.textPrimary, flex: 1 }}>{r.marker}</span>
              <span style={{ fontFamily: FONT_DISPLAY, fontSize: 12, color: C.textSecondary }}>{r.value} {r.unit}</span>
            </label>
          ))}
          <PrimaryButton onClick={saveReadings}>Save to Labs</PrimaryButton>
        </div>
      )}
    </Card>
  );
}

